#!/usr/bin/env bash
# Does `packages/pcfont` turn outlines into the right pixels?
#
# The font is generated by `scripts/fixtures/font/make.py` from outlines
# written there rather than vendored from the system, so the right answer is
# arithmetic: a 500x500 unit box at 12 pixels and 1000 units per em is six
# pixels of solid coverage, and the shapes below are checked against that
# rather than against a picture somebody eyeballed.
#
# The shapes are pinned as text because that is what makes a regression
# readable.
#
# `nested` is the one that earns its place, and it was added because the gate
# did not have it. `ring` -- a box with a hole wound the other way -- does NOT
# tell nonzero winding from even-odd: with alternating directions the running
# sum is only ever 0 or 1, and the two rules agree there. Swapping the rule
# left every shape identical and the gate green. `nested` winds both boxes the
# same way, so the sum reaches 2, where nonzero fills solid and even-odd
# punches a hole.
set -eu
cd "$(dirname "$0")/.."

GRASM=${GRASM:-./target/release/grasm}
FONT=scripts/fixtures/font/shapes.ttf
work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT

[ -f "$FONT" ] || { echo "    $FONT is missing; run scripts/fixtures/font/make.py"; exit 1; }

if ! "$GRASM" build packages/pcfont-demo/src/main.gr --native -o "$work/pcfont" \
    >"$work/build.log" 2>&1; then
    echo "    the rasteriser did not build:"
    sed 's/^/      /' "$work/build.log"
    exit 1
fi

fail=0
check() {
    local name="$1" ch="$2" size="$3"
    shift 3
    local got want
    # The demo brackets each row with `|` so trailing spaces are visible when
    # a person reads it; the rulers are not part of the shape.
    got=$("$work/pcfont" "$FONT" "$ch" "$size" | tail -n +2 | sed 's/^|//; s/|$//')
    want=$(printf '%s\n' "$@")
    if [ "$got" != "$want" ]; then
        echo "    $name differs:"
        diff <(printf '%s\n' "$want") <(printf '%s\n' "$got") | sed 's/^/      /'
        fail=1
    fi
}

# A 500x500 box offset 100 units right, at 12px: six solid pixels with the
# offset split across the two edge columns.
check square A 12 \
'         ' \
' +#####. ' \
' +#####. ' \
' +#####. ' \
' +#####. ' \
' +#####. ' \
' +#####. ' \
'         ' \
'         '

# The hole must be hollow.
check ring B 16 \
' +++++++++++++ ' \
' ############+ ' \
' ############+ ' \
' ###+++++++##+ ' \
' ###.     +##+ ' \
' ###.     +##+ ' \
' ###.     +##+ ' \
' ###.     +##+ ' \
' ###.     +##+ ' \
' ###+.....+##+ ' \
' ############+ ' \
' ############+ ' \
' ############+ ' \
'               ' \
'               '

# A straight diagonal, anti-aliased.
check triangle C 16 \
' .             ' \
' #.            ' \
' ##.           ' \
' ###.          ' \
' ####.         ' \
' #####.        ' \
' ######.       ' \
' #######.      ' \
' ########.     ' \
' #########.    ' \
' ##########.   ' \
' ###########.  ' \
' ############. ' \
'               ' \
'               '

# A quadratic, so the Bezier flattening is in the answer.
check curve D 16 \
'               ' \
'               ' \
'               ' \
'               ' \
'               ' \
'               ' \
'      ...      ' \
'    .####+     ' \
'   .#######    ' \
'   ########+   ' \
'  +#########.  ' \
' .###########  ' \
' +###########+ ' \
'               ' \
'               '

# Two boxes wound the same way: solid under nonzero winding, holed under
# even-odd. This is the shape that makes the rule observable.
check nested F 16 \
' +++++++++++++ ' \
' ############+ ' \
' ############+ ' \
' ############+ ' \
' ############+ ' \
' ############+ ' \
' ############+ ' \
' ############+ ' \
' ############+ ' \
' ############+ ' \
' ############+ ' \
' ############+ ' \
' ############+ ' \
'               ' \
'               '

[ "$fail" -eq 0 ] || exit 1
echo "    glyphs: 5 shapes pinned   nonzero winding, anti-aliasing, Beziers"
